insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('mapping', 'intermediate', 'module', 'm01-a-second-surface', 1, 'What does the Professional tier add to the single depth surface the Associate tier produced?', '["A second gridding method, so that the same picks can be interpolated by a spline and by inverse distance and the two results compared.", "A second surface gridded on the same frame, so that two grids can be combined into a third by arithmetic at every node.", "A finer cell size, which resolves structure the 100 m grid of the tier below was too coarse to show.", "A validation step that measures how far the mapped depth is likely to be from the truth at a location with no well."]'::jsonb, 1, 'This tier grids BASE_SAND on the frame the top surface already used and subtracts, which turns a grid from a picture into a number at every node. Validation belongs to the Expert tier and the cell size and method are unchanged.'),
  ('mapping', 'intermediate', 'module', 'm01-a-second-surface', 2, 'The Ekene isochore capstone grades six fields. Which of them involves no gridding at all?', '["The live isochore node count of 201, which is graded to zero tolerance.", "The thickness at prospect P-1, which the panel reads as 34.050048828125 m.", "The mean of the six well thicknesses, 31.166666666666668 m.", "The isochore minimum of 25 m."]'::jsonb, 2, 'The well mean is six subtractions at the wells averaged, with no frame, spline, mask or cell size involved. The other three are all readings of the gridded isochore.'),
  ('mapping', 'intermediate', 'module', 'm01-a-second-surface', 3, 'Which pair of Ekene wells carries the thickest and the thinnest SAND interval?', '["Ekene-2 at 36 m is thickest and Ekene-4 at 25 m is thinnest.", "Ekene-6 at 34 m is thickest and Ekene-3 at 29 m is thinnest, with Ekene-2 second.", "Ekene-3 at 29 m is thickest and Ekene-5 at 31 m is thinnest of the six wells.", "Ekene-1 at 32 m is thickest and Ekene-2 at 36 m is thinnest."]'::jsonb, 0, 'The six thicknesses are 32, 36, 29, 25, 31 and 34 m, so Ekene-2 is thickest and Ekene-4 thinnest, a spread of 11 m on a mean of 31.17 m.'),
  ('mapping', 'intermediate', 'module', 'm01-a-second-surface', 4, 'Ekene-4 is the thinnest well at 25 m and it is also the deepest, with a TOP_SAND at 1590 m. Ekene-2 is the thickest at 36 m and is second deepest. What does that pairing rule out?', '["It rules out the picks being reliable, because a deep well should carry a thicker interval than a shallow one.", "It rules out the two surfaces having been gridded on the same frame, since a shared frame would force thickness and depth to correlate.", "It rules out the sand thinning uniformly onto a structural high.", "It rules out the interval being a single depositional unit, because a single unit cannot vary by a third across one field."]'::jsonb, 2, 'A thin deep well and a thick deep well together mean thickness does not track depth on this field, so the tidiest story of uniform thinning onto a high does not fit. Nothing about the picks or the frame follows from it.'),
  ('mapping', 'intermediate', 'module', 'm01-a-second-surface', 5, 'How would you test, before gridding anything, whether the two Ekene surfaces are parallel?', '["Grid both surfaces and check whether their contour intervals come out equal.", "Compare the map mean of the top surface against the map mean of the base surface.", "Check whether the two surfaces have the same number of live nodes after the mask is applied.", "Subtract each well''s own two picks and see whether the six differences are constant."]'::jsonb, 3, 'Parallel surfaces differ by a constant, so the six well thicknesses would all be equal. They are 32, 36, 29, 25, 31 and 34, so the surfaces are not parallel and the isochore will be a real map rather than a flat sheet.'),
  ('mapping', 'intermediate', 'module', 'm01-a-second-surface', 6, 'A well''s TOP_SAND is picked 3 m too deep and its BASE_SAND is correct. What happens to the two maps?', '["The structure looks 3 m lower and the sand looks 3 m thinner at that well.", "The structure looks 3 m lower and the thickness map is unaffected.", "The thickness map gains 3 m at that well and the depth map is unaffected.", "Both maps are unaffected, because a spline redistributes a single-well error across its neighbours."]'::jsonb, 0, 'A top error moves the depth map and the thickness map in opposite directions, because thickness is base minus top. A base error moves only the thickness map, by the full amount.'),
  ('mapping', 'intermediate', 'module', 'm01-a-second-surface', 7, 'Which pick error is the one most likely to survive a review unnoticed?', '["A base pick 6 m too deep in one well, which widens the thickness range beyond the other five.", "A top pick 5 m too shallow in one well, which pulls the crest toward that well.", "Both picks in one well shifted the same way by the same amount.", "A swapped top and base in one well, which gives that well a negative thickness."]'::jsonb, 2, 'A systematic datum error moves both picks together, so the difference is unchanged, the depth map moves and the isochore says nothing about it. That is why the isochore is a good quality control on the picks and a bad one on the datum.'),
  ('mapping', 'intermediate', 'module', 'm01-a-second-surface', 8, 'What five numbers define the Ekene capstone frame?', '["Origin (400, 800), cell 100 m by 100 m, and 25 by 20 nodes.", "Origin (600, 1000), cell 100 m by 100 m, and 25 by 20 nodes.", "Origin (400, 800), cell 50 m by 50 m, and 45 by 35 nodes.", "Origin (0, 0), cell 100 m by 100 m, and 24 by 19 nodes."]'::jsonb, 0, 'The frame is an origin, a cell size in each direction and a node count in each direction, here (400, 800), 100 by 100 m and 25 by 20, giving 500 nodes over 2400 m by 1900 m.'),
  ('mapping', 'intermediate', 'module', 'm01-a-second-surface', 9, 'Two grids are subtracted when their origins differ by exactly one cell in y. What does the result look like?', '["An array-length error, because a shifted origin changes the number of nodes.", "A map with a band of blanks along one edge, which announces the misalignment at a glance.", "A smooth, plausible, fully contoured map whose every value is a difference between two unrelated locations.", "A map that is correct in the middle and wrong only at the edges, where the shift leaves no partner node."]'::jsonb, 2, 'The arithmetic pairs element i of one array with element i of the other regardless of where those elements sit, and a smooth surface minus a shifted smooth surface is still smooth. Nothing about the picture announces the problem.'),
  ('mapping', 'intermediate', 'module', 'm01-a-second-surface', 10, 'Why does the teaching workflow compute one frame and pass it to both gridding calls, rather than computing a frame per surface and comparing them?', '["Because computing two frames costs twice as much time on a large grid.", "Because a construction that cannot disagree with itself beats a check that can pass by luck and fail the day a well is added.", "Because the engine rejects a second frame object once the first surface has been gridded.", "Because a frame derived from base picks is always coarser than one derived from top picks."]'::jsonb, 1, 'On this dataset two frames would agree, since both surfaces use the same six well locations, but that is a property of the data rather than of the method. A missing base pick would shrink one frame silently.'),
  ('mapping', 'intermediate', 'module', 'm01-a-second-surface', 11, 'Which three properties of two grids must match before they can be subtracted?', '["The origin, the cell size and the node count.", "The contour interval, the colour scale and the extrapolation limit.", "The control count, the interpolation method and the mask.", "The map mean, the live node count and the frame origin."]'::jsonb, 0, 'Those three are what makes element i of one array the same place on the ground as element i of the other. A cell size or node count mismatch usually fails loudly; an origin offset does not.'),
  ('mapping', 'intermediate', 'module', 'm01-a-second-surface', 12, 'On the isochore explorer, what is posted at each well when the isochore is displayed?', '["The mapped thickness sampled from the isochore grid at that well''s own coordinates.", "The well''s TOP_SAND pick, so that the depth and thickness views stay comparable.", "The difference between the mapped and the measured thickness, so that honouring can be read directly.", "The well''s own measured thickness, base pick minus top pick, with no gridding involved."]'::jsonb, 3, 'The posting is a measurement, so comparing it against the shading around it is a direct quality check on the map. On the depth surfaces the posting is the pick itself.'),
  ('mapping', 'intermediate', 'module', 'm01-a-second-surface', 13, 'The isochore explorer offers cell sizes of 50, 100 and 200 m. Which does the capstone use, and why are the other two on the panel?', '["It uses 50 m, and the coarser settings are there to show how much detail a coarse grid loses.", "It uses 100 m, and the others show which readings are about the settings rather than about the rock.", "It uses 200 m, and the finer settings are there for learners who want a smoother picture.", "It uses whichever setting gives 201 live nodes, which is why three are offered."]'::jsonb, 1, 'The capstone fixes 100 m, two pad cells and an 800 m limit. Module 3 uses the other two settings to sort the capstone fields into those the grid moves and those it cannot touch.'),
  ('mapping', 'intermediate', 'module', 'm01-a-second-surface', 14, 'Why does the isochore have exactly six control points rather than twelve?', '["Because the mask discards half of the control before the spline is fitted.", "Because six of the twelve picks fall outside the convex hull of the well pattern.", "Because the engine decimates control points down to six whenever two surfaces are combined.", "Because the same six wells constrain both surfaces, and two maps of six points are not a map of twelve."]'::jsonb, 3, 'The isochore is a derived quantity with exactly the same control as the surfaces it came from. It looks like an independent measurement of thickness because it has its own contours and extremes, and it is not.'),
  ('mapping', 'intermediate', 'module', 'm01-a-second-surface', 15, 'Which statement about the two capstone means is correct?', '["The well mean is the correct number and the map mean is biased by the interpolator.", "Both are honest averages of the same rock and they answer different questions.", "The map mean is the correct number and the well mean is obsolete once a map exists.", "They differ only because the map mean includes nodes that the mask should have removed."]'::jsonb, 1, 'The well mean weights six wells equally and the map mean weights 201 nodes equally, which is a weighting by area. Neither is an error and quoting one when the other was wanted is how a volume goes wrong with no arithmetic mistake anywhere.'),
  ('mapping', 'intermediate', 'module', 'm02-subtracting-grids', 1, 'In the isochore calculation, what is subtracted from what, and why in that order?', '["Top minus base, because the top surface is the reference the interval hangs from.", "Base minus top, because depths are positive downward and the base is deeper.", "Whichever order gives a positive result at the first well, checked well by well as the map is built.", "Shallower minus deeper, because thickness is conventionally reported as a reduction in depth."]'::jsonb, 1, 'TOP_SAND at Ekene-1 is 1548 and BASE_SAND is 1580, so base minus top gives a positive 32 m. The engine takes the deep surface first in its call signature for exactly this reason.'),
  ('mapping', 'intermediate', 'module', 'm02-subtracting-grids', 2, 'What happens if the two surfaces are subtracted in the wrong order?', '["The gridder rejects the call, because a negative thickness is not a valid surface.", "The map is unchanged, because contouring takes the absolute value of each node.", "You get a map of negative numbers that contours perfectly well.", "Only the nodes between wells go negative, so the error shows up as a patchy map."]'::jsonb, 2, 'Contouring does not care about sign, so every value is simply the negative of the correct one. The error is easy to miss when the colour scale is rescaled to fit.'),
  ('mapping', 'intermediate', 'module', 'm02-subtracting-grids', 3, 'TOP_SAND at P-1 reads 1542.619873046875 m and BASE_SAND reads 1576.669921875 m. What is the isochore there, and does it matter whether you subtract first or sample first?', '["34.050048828125 m, and the order does not matter because both sampling and subtraction are linear.", "34.050048828125 m, but only if the isochore is built first, since sampling two surfaces separately introduces interpolation error.", "34.05 m, and the order matters because bilinear sampling of a difference is not the difference of two bilinear samples.", "3119.289794921875 m, since the two surfaces must be added at a prospect with no well control."]'::jsonb, 0, 'Bilinear interpolation is linear, so it commutes with subtraction and a thickness quoted at a location does not depend on whether the isochore was built first.'),
  ('mapping', 'intermediate', 'module', 'm02-subtracting-grids', 4, 'Which property does the isochore inherit from the two surfaces it was built from?', '["Independence, since a difference of two interpolations is a new observation of thickness.", "Its control count, because six wells constrain the top and the same six constrain the base.", "Twice the control, because each well contributes a top pick and a base pick to the result.", "Its contour interval, which is inherited from the top surface so that the two maps stay comparable."]'::jsonb, 1, 'The isochore is a derived quantity with exactly the same six control points as its inputs. Its contour interval is chosen from its own range and comes out at 2 m against the depth map''s 10 m.'),
  ('mapping', 'intermediate', 'module', 'm02-subtracting-grids', 5, 'What is the rule for blanks when two grids are combined?', '["A node is live in the result if it was live in either input, with the missing side extrapolated.", "A node is live in the result only if it was live in both inputs.", "A node is live in the result if it lies inside the convex hull of the combined control points.", "A node is live in the result unless the difference of the two values is negative there."]'::jsonb, 1, 'The output live set is the intersection of the two input live sets, so combining maps can only lose coverage. Combine three surfaces and you keep only the area all three cover.'),
  ('mapping', 'intermediate', 'module', 'm02-subtracting-grids', 6, 'The Ekene isochore keeps all 201 live nodes. Why is that not a general rule?', '["Because the mask depends only on the control locations, and here both surfaces use the same six well positions.", "Because 201 is the largest live count the 800 m limit allows on a 25 by 20 frame, so no combination can exceed it.", "Because the spline honours all six wells on both surfaces, which forces the two masks to agree.", "Because the engine recomputes the mask from the isochore itself once the subtraction has been done."]'::jsonb, 0, 'The hull test and the extrapolation test both use only the x and y of the control, never the z. The two live sets are therefore the same set of nodes rather than merely the same size, and a single missing base pick would break it.'),
  ('mapping', 'intermediate', 'module', 'm02-subtracting-grids', 7, 'Ekene-4 in the northeast has a TOP_SAND pick but no BASE_SAND pick. What happens to the two maps?', '["Both maps lose the northeast, because a well missing one pick is dropped from the control set entirely.", "The depth map keeps 201 live nodes and the isochore falls to 133.", "Both maps keep 201 live nodes, and only the well mean changes, from six wells to five.", "The isochore keeps 201 live nodes but reports a blank at Ekene-4 alone."]'::jsonb, 1, 'The base surface would be controlled by five points, its hull would shrink to exclude the northeast corner, and the intersection leaves 133 nodes. Nothing about the depth map would change, so the loss appears only in the thickness map and in anything computed from it.'),
  ('mapping', 'intermediate', 'module', 'm02-subtracting-grids', 8, 'A top surface has 480 live nodes, a base surface has 350, and the two live sets overlap over 340. What does the isochore cover, and what belongs in the report?', '["350 nodes, since the base surface is the limiting one and its coverage is what survives.", "415 nodes, the mean of the two coverages, because the overlap is not a hard boundary.", "340 nodes, and the report should state that as 71 percent of the top surface''s coverage and name the reason.", "480 nodes, because the top surface defines the mapped area and the base is interpolated into it."]'::jsonb, 2, 'The isochore has the intersection, 340. A volume from it covers 71 percent of the mapped structure and the remaining 29 percent is unquantified volume rather than zero volume.'),
  ('mapping', 'intermediate', 'module', 'm02-subtracting-grids', 9, 'Gridding the six well thicknesses directly gives a maximum of 35.897666931152344 m against 35.897705078125 m by subtraction. What does that tell you?', '["That the two routes are the same calculation and the difference is floating point rounding.", "That the direct route is slightly less accurate, since it grids differences rather than measurements.", "That the two routes agree only at the extremes, and will diverge in the middle of the map.", "That one of the two runs used a different extrapolation limit, since exact agreement is expected."]'::jsonb, 0, 'The largest disagreement anywhere is 0.000110626220703125 m and the average is about 0.00004 m, a tenth of a millimetre on values of about 32 m.'),
  ('mapping', 'intermediate', 'module', 'm02-subtracting-grids', 10, 'Why must gridding-then-subtracting and subtracting-then-gridding agree on this dataset?', '["Because both routes are run on the same frame, and a shared frame forces any two grids of the same field to agree.", "Because the mask removes every node where the two routes could differ, leaving only the exactly honoured well nodes.", "Because the spline is linear in its control values and both surfaces are fitted at the same six locations.", "Because the spline is fitted by least squares, which minimises the difference between any two derived surfaces."]'::jsonb, 2, 'The system is A w = z with A built from the control locations alone, so the weights of the difference are the difference of the weights.'),
  ('mapping', 'intermediate', 'module', 'm02-subtracting-grids', 11, 'Which condition, if lost, would break the equivalence of the two routes?', '["The two surfaces being gridded from the same control locations.", "The prospect P-1 landing exactly on a grid node in the chosen frame.", "The contour interval being the same on both surfaces.", "The two surfaces having similar ranges, so that their splines bend by similar amounts."]'::jsonb, 0, 'Same control locations, same method and settings, and same mask are the three conditions. A well with a top pick and no base pick gives the two systems different matrices and the routes diverge.'),
  ('mapping', 'intermediate', 'module', 'm02-subtracting-grids', 12, 'If the two routes agree to rounding, why does the course still recommend the subtraction route?', '["Because the direct route cannot honour the well thicknesses exactly, so it fails the control check.", "Because the direct route is more sensitive to the cell size, which makes its statistics harder to quote.", "Because subtraction is the only route the engine''s isochore function supports.", "Because subtraction produces the two depth surfaces as well, and volumetrics and well planning need them."]'::jsonb, 3, 'The depth surfaces have to be gridded anyway, at which point the direct route is extra work that yields a duplicate answer.'),
  ('mapping', 'intermediate', 'module', 'm02-subtracting-grids', 13, 'The isochore reproduces five of the six well thicknesses exactly and returns a blank at Ekene-2. Why the blank?', '["Because Ekene-2''s base pick is missing, so no thickness exists there to be mapped.", "Because Ekene-2 lies outside the 800 m extrapolation limit of every other well in the set.", "Because the spline does not honour control points that sit on the convex hull of the pattern.", "Because (2200, 1150) is not a grid row, so three of its four bilinear corners are dead."]'::jsonb, 3, 'The frame has y0 800 and dy 100, so rows sit at 1100 and 1200 and not at 1150. Bilinear interpolation returns a blank whenever any corner is dead, so the masked grid cannot deliver a value the underlying fit honours exactly.'),
  ('mapping', 'intermediate', 'module', 'm02-subtracting-grids', 14, 'A quality control script samples the isochore at every well and reports a mean absolute difference of 0 over five wells, with Ekene-2 blank. Is that a pass?', '["Yes, and the blank can be dropped, since a mean over five wells is a valid sample of six.", "No, because a mean absolute difference of zero proves the spline has been over-fitted to its control.", "No, because control honouring must be checked at the fit rather than at the grid in every case.", "Yes, but only with the blank stated, because the sixth well is on the edge where the surface is least constrained."]'::jsonb, 3, 'Reporting five of six exact with one unsampleable is complete and honest. Reporting five of five, quietly dropping Ekene-2, is not.'),
  ('mapping', 'intermediate', 'module', 'm02-subtracting-grids', 15, 'What is the difference between an isochore and an isopach, and which does this tier produce?', '["An isochore is a thickness map from wells and an isopach is one from seismic; this tier produces an isochore.", "An isochore is thickness perpendicular to bedding and an isopach is vertical thickness; this tier produces an isopach.", "An isochore is vertical thickness and an isopach is thickness perpendicular to bedding; this tier produces an isochore.", "An isochore is gross thickness and an isopach is net thickness; this tier produces an isopach."]'::jsonb, 2, 'Subtracting two depth surfaces at fixed map coordinates gives vertical thickness. The two are related by t_isopach = t_isochore cos(theta).'),
  ('mapping', 'intermediate', 'module', 'm03-reading-the-thickness-map', 1, 'At the capstone settings the isochore minimum is 25 m. Where does it sit and what kind of number is it?', '["At node (2200, 1200), and it is the spline undershooting between two thin wells.", "At Ekene-4''s own node, so it is a measurement rather than a prediction.", "At the southwest corner of the mask, and it is the least constrained value on the map.", "Halfway between Ekene-4 and Ekene-3, and it is an interpolation between the two thinnest wells."]'::jsonb, 1, 'Ekene-4 at (2600, 2500) is the thinnest well at 25 m, it lands exactly on a grid node, and the spline honours it. Nothing on the map is thinner, because the spline has no reason to go below its control in that corner.'),
  ('mapping', 'intermediate', 'module', 'm03-reading-the-thickness-map', 2, 'The mapped maximum is 35.897705078125 m at node (2200, 1200), while Ekene-2 at (2200, 1150) measures 36 m. What is going on?', '["The spline has undershot its thickest control point, the mirror image of the depth crest overshoot.", "The mask has clipped the map 50 m short of Ekene-2, so the thickest ground is outside the live area.", "The grid has no node at Ekene-2, so the nearest node it does have is 0.102 m thinner.", "Ekene-2''s pick is being down-weighted because it sits on the boundary of the control hull."]'::jsonb, 2, 'At a 50 m cell a node lands on (2200, 1150) and the mapped maximum becomes exactly 36 m. The fit honoured 36 in both runs; only the sampling changed.'),
  ('mapping', 'intermediate', 'module', 'm03-reading-the-thickness-map', 3, 'Which test separates a spline overshoot from a node placement artefact at a mapped extreme?', '["Widen the extrapolation limit and see whether the extreme survives the larger mask.", "Refine the cell size and re-read the extreme.", "Compare the extreme against the mean and check that it lies within two standard deviations.", "Regrid with the extreme well removed and see whether the value returns."]'::jsonb, 1, 'If the extreme moves toward the control values and settles, the coarse grid was missing the right node. If it stays past the control, the fit is doing it and no refinement will help.'),
  ('mapping', 'intermediate', 'module', 'm03-reading-the-thickness-map', 4, 'The Associate tier''s depth crest is 1539.7181 m against a shallowest pick of 1541 m, and at a 50 m cell it reads 1539.6909 m. What does that behaviour identify it as?', '["A node placement artefact, since a finer grid moved the value.", "A masking artefact, since the crest sits close to the edge of the live area.", "A rounding artefact of the float32 grid storage, which refinement makes visible.", "A genuine property of the fit, since refinement leaves it past the control."]'::jsonb, 3, 'A thin-plate spline minimises bending energy and will overshoot beyond its control to do so. Refining the grid does not remove it, so it has to be recognised and reported rather than fixed.'),
  ('mapping', 'intermediate', 'module', 'm03-reading-the-thickness-map', 5, 'At a 200 m cell the isochore minimum reads 26.733154296875 m rather than 25 m. Why?', '["Because the mask is recomputed at each cell size and excludes Ekene-4 at 200 m.", "Because the 200 m frame extends further past the wells, which dilutes the thin corner.", "Because a coarse grid smooths the surface before sampling it, which removes local extremes.", "Because the coarse grid has no node at Ekene-4, so the nearest node it has is thicker."]'::jsonb, 3, 'It is node placement in the other direction, and the test confirms it: refining to 100 m brings the minimum back to exactly 25 m and it stays there at 50 m.'),
  ('mapping', 'intermediate', 'module', 'm03-reading-the-thickness-map', 6, 'Where are the crest of the depth map and the thick spot of the isochore on this field?', '["Both near Ekene-6 in the centre, since the interior well controls a third of the map.", "The crest is near Ekene-2 in the southeast and the thick spot near Ekene-3 in the north.", "About 1100 m apart, the crest at (1400, 2000) and the thick spot at (2200, 1200).", "At the same node, which is why the prospect P-1 was placed between them."]'::jsonb, 2, 'They sit in different quadrants of a field 2400 m across. Structure and thickness are made by different processes at different times, so coincidence is the case that needs explaining rather than the separation.'),
  ('mapping', 'intermediate', 'module', 'm03-reading-the-thickness-map', 7, 'Why is there no reason for a crest and a thick spot to coincide?', '["Because thickness is depositional while structure is what happened to the interval later on, after burial.", "Because the spline overshoots on depth and undershoots on thickness, which pushes the two extremes apart.", "Because the two maps are gridded from different control sets, so their extremes are independent by construction.", "Because contouring at different intervals moves the apparent position of an extreme on each map."]'::jsonb, 0, 'Thickness is mostly set at deposition and structure by later burial and deformation. When they do coincide it is usually because something links them, such as growth over an existing structure or differential compaction.'),
  ('mapping', 'intermediate', 'module', 'm03-reading-the-thickness-map', 8, 'Three locations are ranked for a well. A maps at 1541 m depth and 28 m thick, B at 1545 m and 34 m, C at 1548 m and 35 m. What does the pair of maps say about a depth-only ranking?', '["It is correct, since 4 m of extra structure outweighs a 6 m thickness difference in almost every case.", "It inverts the order, because A carries 21 percent less rock than B for 4 m of structure.", "It is unusable, because depth and thickness cannot be compared without a contact and a recovery factor.", "It is safe as long as the three locations lie within one contour interval of each other."]'::jsonb, 1, 'Unless the contact is shallow enough that A''s extra 4 m buys column B does not have, B is the better location on this evidence. Neither number decides on its own and the calculation that combines them properly is volumetrics.'),
  ('mapping', 'intermediate', 'module', 'm03-reading-the-thickness-map', 9, 'The isochore at P-1 reads 34.050048828125 m and the nearest well, Ekene-6 at 361 m, measures 34 m. What is the honest way to state the reading?', '["That the prospect carries 34.05 m of sand, a mapped value with a tolerance of 0.1 m.", "That the prospect carries between 25 and 36 m of sand, the range of the six wells.", "That the map predicts about 34 m because Ekene-6 does, 361 m away.", "That the prospect thickness cannot be quoted at all, since no well has been drilled there."]'::jsonb, 2, 'A spline near a control point mostly reports that control point. The next nearest control is 728 m away at Ekene-3, so the number is an interpolation dominated by one well.'),
  ('mapping', 'intermediate', 'module', 'm03-reading-the-thickness-map', 10, 'The thickness at P-1 is byte-identical at 50, 100 and 200 m cells. Why?', '["Because P-1 lands exactly on a node in all three frames, and a node value is the fit itself.", "Because the capstone fixes the cell size at 100 m before any field is graded.", "Because the mask keeps P-1 well inside the live area at every setting.", "Because bilinear interpolation between neighbouring nodes is exact on a smooth surface."]'::jsonb, 0, 'The spline is a continuous function defined everywhere and the grid is a sampling of it. Values read at nodes are grid independent; statistics computed over nodes are not.'),
  ('mapping', 'intermediate', 'module', 'm03-reading-the-thickness-map', 11, 'Which quantity on the isochore panel does change with cell size?', '["The thickness at prospect P-1.", "The map mean, which reads 32.2873, 32.2543 and 32.2720 at 50, 100 and 200 m.", "The mean of the six well thicknesses.", "The sign convention of the subtraction."]'::jsonb, 1, 'The map mean is an average over the node set, and both the number and the placement of nodes change with the cell size. The well mean involves no gridding at all.'),
  ('mapping', 'intermediate', 'module', 'm03-reading-the-thickness-map', 12, 'How does the panel choose a contour interval?', '["It takes the range, divides it by ten and then rounds up to a nice 1, 2 or 5.", "It fixes ten intervals across the range and reports whatever step that gives.", "It uses the standard deviation of the live nodes, rounded to the nearest metre.", "It matches the interval of the surface last displayed, so that maps stay comparable."]'::jsonb, 0, 'On TOP_SAND the range is 50.28 m, a tenth is 5.03 and the interval is 10 m. On the isochore the range is 10.90 m, a tenth is 1.09 and the interval is 2 m.'),
  ('mapping', 'intermediate', 'module', 'm03-reading-the-thickness-map', 13, 'The isochore is contoured at 2 m and the depth map at 10 m. What does the finer interval mean?', '["That the thickness map resolves detail the depth map cannot, since it is built from twice as many picks.", "That the isochore is more precise, because subtracting two surfaces cancels part of their error.", "That the isochore range is smaller, and nothing more.", "That the isochore has more live nodes, so the contouring algorithm has more to work with."]'::jsonb, 2, 'Both maps come from the same six wells, the same spline and the same mask. A contour interval describes the range of the map, not its quality, and a fine interval reads as authority a reader may grant without thinking.'),
  ('mapping', 'intermediate', 'module', 'm03-reading-the-thickness-map', 14, 'At a 200 m cell the isochore range falls to 9.16 m and the map is contoured at 1 m, giving nine levels. Why is that worth flagging?', '["Because the coarsest grid, with 50 live nodes rather than 201, gets the finest interval.", "Because nine levels is below the ten the rule targets, which means the rule has failed on this range.", "Because a 1 m interval on a thickness map implies the picks were made to the decimetre.", "Because the 200 m grid has lost the maximum as well, so both ends of the range have moved."]'::jsonb, 0, 'The visual impression is exactly backwards: the map that looks most detailed is built from the fewest nodes. The defence is to quote the interval and the cell size together.'),
  ('mapping', 'intermediate', 'module', 'm03-reading-the-thickness-map', 15, 'Across 50, 100 and 200 m cells the map mean spans 32.2543 to 32.2873 m, a spread of 0.033 m. What does that imply about which map statistics to trust?', '["That every statistic is stable, since a sixteenfold change in node count moved nothing by more than 0.04 m.", "That the mean should be quoted only at the cell size the capstone fixes, since it moves at every other setting.", "That the map is under-sampled at 200 m, since a stable mean over 50 nodes is a coincidence.", "That the mean is essentially a property of the surface, while the extremes and the node count are more sensitive."]'::jsonb, 3, 'Refining a grid mostly adds nodes between existing ones, where the spline value is close to what its neighbours already reported. Averages are robust to that and extremes, which are single nodes by definition, are not.'),
  ('mapping', 'intermediate', 'module', 'm04-two-honest-means', 1, 'How is the well mean of the Ekene SAND computed?', '["By averaging the isochore over the six nodes the wells land on, which is where the map is exact.", "By subtracting each well''s own two picks and averaging the six results.", "By weighting each well by the map area nearest to it and averaging.", "By averaging the top picks and the base picks separately and subtracting the two means."]'::jsonb, 1, 'It is (32 + 36 + 29 + 25 + 31 + 34) / 6 = 187 / 6 = 31.166666666666668 m. No frame, spline, mask or cell size enters it.'),
  ('mapping', 'intermediate', 'module', 'm04-two-honest-means', 2, 'Why does the capstone grade the well mean to 0.05 m while the gridded thickness fields get 0.1 m?', '["Because it is a smaller number, so the same relative tolerance is a tighter absolute one.", "Because it is measured at wells, where the picks are known to the decimetre rather than to the metre.", "Because there is nothing in it to be uncertain about, so any wrong answer is an arithmetic slip rather than a modelling choice.", "Because it is the first field a learner computes, so an error there would propagate into the other five."]'::jsonb, 2, 'The picks are exact integers, the subtraction is exact and the division by six is exact to float precision. The gridded fields carry a wider tolerance because they depend on the interpolator, the mask and node placement.'),
  ('mapping', 'intermediate', 'module', 'm04-two-honest-means', 3, 'Which of these is a legitimate use of the well mean?', '["As the thickness input to a gross rock volume over the mapped area.", "As the honest summary of what six wells have measured, with its count and range.", "As the reference an interpolator should be tuned to reproduce as its area average.", "As an estimate of the average thickness of the field, since it rests only on measurements."]'::jsonb, 1, 'It needs no assumptions and survives any change of mapping method. It is not an estimate of the field average, because wells are drilled where reservoir is already expected rather than at random.'),
  ('mapping', 'intermediate', 'module', 'm04-two-honest-means', 4, 'A mean of six thicknesses spanning 25 to 36 m has a standard error of roughly 1.6 m. What does that say?', '["That the picks carry an uncertainty of 1.6 m each, which is what the spread measures.", "That the map mean of 32.25 m is inside the sampling error of the well mean, so the two are the same number.", "That six wells are enough, since 1.6 m is within the 2 m contour interval of the isochore.", "That the true field average could sit a metre and a half either side of 31.17 m on sampling grounds alone, before bias is considered."]'::jsonb, 3, 'The spread of 11 m is more than a third of the mean, so the interval genuinely varies and one central number is a poor summary. Quote it as 31.17 m, mean of six wells, range 25 to 36 m.'),
  ('mapping', 'intermediate', 'module', 'm04-two-honest-means', 5, 'A seventh well finds 40 m of sand. What happens to the well mean and what should be said about it?', '["It falls, because the new well widens the range and the mean is pulled toward the centre of it.", "It rises to 32.43 m, which confirms that the six-well mean was biased low and should be replaced.", "It is unchanged, because a new well outside the original control set does not enter the mean.", "It rises to 32.43 m, which measures how unstable a mean of six really is."]'::jsonb, 3, 'The new mean is (187 + 40) / 7 = 32.43 m, a rise of 1.26 m from one well. It is also worth asking why the new well is the thickest, since drilling it on the thickest part of the isochore makes the well set more biased rather than more representative.'),
  ('mapping', 'intermediate', 'module', 'm04-two-honest-means', 6, 'The isochore''s map mean of 32.25429068038713 m averages 201 live nodes on a regular 100 m lattice. What kind of average is that?', '["A well-weighted average, since every node traces back to the six wells that constrain it.", "A spline-weighted average, since nodes near control carry more weight than nodes between wells.", "An area-weighted average, since every node stands for the same 10,000 m squared of ground.", "An unweighted average of measurements, since a node value is the fit evaluated exactly."]'::jsonb, 2, 'The lattice is regular, so averaging nodes equally is averaging by area. That is the single most important thing to understand about this number.'),
  ('mapping', 'intermediate', 'module', 'm04-two-honest-means', 7, 'The panel reports 146 of 201 live nodes above the well mean. What is that tile for?', '["It measures the asymmetry that causes the gap, with 73 percent of the area above the well mean.", "It counts the nodes the mask should have removed, since a node above every well value is over-extrapolated.", "It shows how many nodes lie inside the convex hull of the control points.", "It reports how many nodes would change if the cell size were refined from 100 m to 50 m."]'::jsonb, 0, 'Only 55 nodes sit below the well mean. That strong asymmetry is the direct cause of the map mean sitting 1.0876 m above the well mean.'),
  ('mapping', 'intermediate', 'module', 'm04-two-honest-means', 8, 'Which mean belongs in a gross rock volume calculation, and why?', '["The well mean, because it rests on measurements while the map mean rests on interpolation between them.", "The map mean, because volume is thickness integrated over area and an area-weighted mean is what that integral computes.", "Either, since the two differ by only 3.4 percent, which is inside normal volumetric uncertainty.", "The average of the two, which balances the measured control against the mapped area."]'::jsonb, 1, 'Using the well mean computes a volume as though each well''s thickness applied to a sixth of the field, which the map explicitly contradicts. The well mean feels more trustworthy, being made of measurements, which is why the error survives review.'),
  ('mapping', 'intermediate', 'module', 'm04-two-honest-means', 9, 'The extrapolation limit is widened from 800 m to 1200 m. What happens to the map mean on this field, and is the change informative?', '["It rises, because a wider mask reaches further up the flanks toward the crest, and the rise is a real gain in coverage.", "It is unchanged, because the mask does not affect an average taken over live nodes.", "It falls, because the added edge nodes are mostly thin, and the change measures the mask rather than the reservoir.", "It falls, and the fall is informative because it shows the previous mask was excluding real reservoir."]'::jsonb, 2, 'Widening the limit can only add nodes that were more than 800 m from every well, all near the edges of the hull, and on this field the far corners lie toward the thinnest well. Those added values are also the least reliable on the map.'),
  ('mapping', 'intermediate', 'module', 'm04-two-honest-means', 10, 'Assigning every live node to its nearest well gives Ekene-6 68 nodes and Ekene-4 18. What does that comparison establish?', '["That Ekene-6 is the best constrained well on the map and Ekene-4 the least.", "That the mask has clipped Ekene-4''s surroundings more aggressively than it should have.", "That the map weights Ekene-6 at 33.8 percent and Ekene-4 at 9.0 percent, against a sixth each in the well mean.", "That the spline honours Ekene-6 over a wider area than it honours Ekene-4."]'::jsonb, 2, 'Ekene-6 is thick at 34 m and gained the most weight; Ekene-4 is thinnest at 25 m and lost the most. The area weighting has systematically promoted the thick wells and demoted the thin one.'),
  ('mapping', 'intermediate', 'module', 'm04-two-honest-means', 11, 'Why does Ekene-6 dominate the area weighting?', '["Because it is the only well inside the hull of the others, so it is the nearest control for the whole middle of the field.", "Because it is the thickest well, and a spline pulls more area toward its larger control values.", "Because it sits closest to prospect P-1, which the frame is centred on.", "Because it was drilled last, so the gridder weights it above the earlier wells."]'::jsonb, 0, 'The reason is geometric rather than geological. The five hull wells each speak only for their own corner and lose half of their surroundings to the mask.'),
  ('mapping', 'intermediate', 'module', 'm04-two-honest-means', 12, 'The gap between the two means decomposes as 31.167 to 31.801 to 32.254. What are the two steps?', '["Area weighting contributes about two thirds and the spline shape the rest.", "The mask contributes about two thirds by discarding thin edge nodes, and rounding contributes the rest.", "The spline contributes about two thirds by overshooting near the crest, and area weighting contributes the rest.", "Node placement contributes about two thirds, and the choice of a 100 m cell contributes the rest."]'::jsonb, 0, 'Area weighting accounts for +0.634 m and the spline shape for +0.453 m. Neither is an error: the area weighting is correct behaviour for anything multiplied by area, and the spline departure is the price of interpolation.'),
  ('mapping', 'intermediate', 'module', 'm04-two-honest-means', 13, 'A reviewer asks that the map be adjusted so its area average equals the well average. What is the answer?', '["That the adjustment is standard practice, since a map that disagrees with its own control has not converged.", "That the adjustment would break the map, because forcing the area average would move the surface away from the wells or away from the minimum-bending fit.", "That the adjustment is unnecessary here, because the gap of 1.09 m is inside the 2 m contour interval.", "That the adjustment should be applied to the well mean instead, by weighting each well by its nearest-node area."]'::jsonb, 1, 'The map already honours every well exactly at its own location, which is the honouring that matters. There is nothing to reconcile: two different questions have two different answers.'),
  ('mapping', 'intermediate', 'module', 'm04-two-honest-means', 14, 'What does using the well mean instead of the map mean cost on the Ekene gross rock volume?', '["About 2.19 million cubic metres, or 3.4 percent, understated.", "About 2.19 million cubic metres, or 3.4 percent, overstated.", "Nothing, because the live node count and the cell area dominate the calculation.", "About 12 percent, since the two means differ by more than a metre on a 32 m interval."]'::jsonb, 0, '64,831,124 against 62,645,000 cubic metres. Three and a half percent is too small to look wrong and too large to ignore, and it is systematic, so it biases every field mapped the same way in the same direction.'),
  ('mapping', 'intermediate', 'module', 'm04-two-honest-means', 15, 'On Ekene the map mean sits above the well mean. Is that the general rule?', '["Yes, because a minimum-bending surface always spends more of its area above its control than below it.", "Yes, because area weighting always promotes the interior of a field, which is thicker on almost every field.", "No, because the direction depends on the cell size, which changes the sign of the gap at fine settings.", "No, because the direction depends on where the thick and thin wells sit relative to the control geometry."]'::jsonb, 3, 'Put the thinnest well in the middle of the pattern and the map mean would come out below the well mean by the same mechanism. Assuming a direction from experience on one field is how the error becomes invisible on the next.'),
  ('mapping', 'intermediate', 'module', 'm05-what-an-isochore-is-for', 1, 'How is the gross rock volume of the Ekene SAND computed from the capstone numbers?', '["Mean thickness times the live node count times the cell area, so 32.25429068 x 201 x 10,000 m2.", "Mean thickness times the full frame node count times cell area, giving 32.25429068 x 500 x 10,000 cubic metres.", "Well mean thickness times live node count times cell area, giving 31.16667 x 201 x 10,000 cubic metres.", "Mean thickness times the area of the convex hull of the six wells, measured from the well coordinates."]'::jsonb, 0, 'The sum of thickness times cell area over the live nodes is the same as the mean times the count times the cell area. Dead nodes contribute nothing and the well mean is the wrong average for anything multiplied by area.'),
  ('mapping', 'intermediate', 'module', 'm05-what-an-isochore-is-for', 2, 'What area does the Ekene gross rock volume claim?', '["The licence area the six wells were drilled in, which the frame is sized to cover.", "2.01 square kilometres, the convex hull of six wells clipped at 800 m from the nearest one.", "The full 25 by 20 frame, 2400 m by 1900 m, since the volume is reported over the map.", "The area inside the 26 m contour, which is where the sand is thick enough to matter."]'::jsonb, 1, '201 live nodes at 10,000 square metres each. That area is not a licence block, a fault block or an accumulation, and anything outside it is unquantified volume rather than zero volume.'),
  ('mapping', 'intermediate', 'module', 'm05-what-an-isochore-is-for', 3, 'What is 64.8 million cubic metres a volume of?', '["The pore volume of the SAND interval over the mapped area.", "The hydrocarbon volume in place above the 1560 m contact.", "The recoverable volume once a recovery factor has been applied to the interval.", "All of the SAND interval over the mapped area, whatever is in the pore space."]'::jsonb, 3, 'No net-to-gross, no porosity, no saturation and no contact have been applied. Each of those multiplies the figure by a fraction less than one, so gross rock volume is the largest number in the chain and the easiest to quote out of context.'),
  ('mapping', 'intermediate', 'module', 'm05-what-an-isochore-is-for', 4, 'At a 50 m cell the map has 794 live nodes of 2,500 square metres, a mapped area of 1.985 square kilometres against 2.010 at a 100 m cell. What does the small difference show?', '["That the mask boundary is drawn at a different resolution, so the two areas agree to about one percent.", "That refining the grid recovers real reservoir the coarse grid had excluded from the volume.", "That the 100 m grid overstates the area, since a coarse node claims ground the mask would reject.", "That the extrapolation limit is applied to node centres rather than to node edges at 50 m only."]'::jsonb, 0, 'Node count and cell area move in opposite directions as the cell size changes, so the mapped area is nearly conserved. The residual difference is where the mask boundary falls between nodes.'),
  ('mapping', 'intermediate', 'module', 'm05-what-an-isochore-is-for', 5, 'Widening the extrapolation limit to 1200 m raises the live node count to 260. What happens to the volume, and to confidence in it?', '["The volume rises by about 29 percent and confidence rises with it, since more of the field is now mapped.", "The volume rises by a little less than 29 percent, and the extra is the least defensible part of it.", "The volume is unchanged, because the mean thickness falls in exactly the proportion the area rises.", "The volume falls, because the added nodes are thin and pull the mean down faster than the area grows."]'::jsonb, 1, 'The added nodes sit at the edges of the hull where the surface is least constrained, and on this field the far edges lie toward the thinnest well, so the mean falls slightly. Every added node is more than 800 m from any well.'),
  ('mapping', 'intermediate', 'module', 'm05-what-an-isochore-is-for', 6, 'Four courses share the Ekene field. What does mapping hand to volumetrics?', '["The mean thickness, the mapped area and the live node count.", "The isochore alone, since volumetrics regrids the depth surface with its own settings.", "The top surface, the isochore and the mask.", "The six pairs of picks, so that volumetrics can grid them against its own frame."]'::jsonb, 2, 'The top surface because the contact cuts it, the isochore because it limits the column, and the mask because it defines the area the calculation may claim.'),
  ('mapping', 'intermediate', 'module', 'm05-what-an-isochore-is-for', 7, 'Why is a statistic not part of what crosses the boundary into volumetrics?', '["Because the volume calculation works node by node on the arrays, where a mean would already have destroyed the variation it integrates.", "Because volumetrics recomputes every statistic itself, so passing them would risk two versions of the same number.", "Because a mean computed at a 100 m cell cannot be used at the finer cell size volumetrics requires.", "Because statistics are reporting products and the two courses report separately."]'::jsonb, 0, 'Averages are for reports and the calculation works on the grids. That is why the hand-off is three arrays rather than three numbers.'),
  ('mapping', 'intermediate', 'module', 'm05-what-an-isochore-is-for', 8, 'This course reports 64.83 million cubic metres for the SAND and the volumetrics course reports 22.27 million at a 1560 m contact. Why are they so different?', '["Because the volumetrics course grids on a finer cell, which reduces the mapped area.", "Because the second figure applies a net-to-gross and a porosity that this course does not.", "Because the contact discards nodes deeper than 1560 m and counts only the column above.", "Because the second figure is a recoverable volume and the first is a volume in place."]'::jsonb, 2, 'Neither is wrong. The first covers the whole interval over the whole mapped area and the second covers only the part of the interval above the contact.'),
  ('mapping', 'intermediate', 'module', 'm05-what-an-isochore-is-for', 9, 'If a contact already limits the column, why does volumetrics still need the isochore?', '["Because near the crest the sand runs out before the contact does, so the thickness caps the column.", "Because the isochore supplies the mapped area, which the top surface on its own does not carry.", "Because the isochore is needed to convert measured depth picks into true vertical thickness.", "Because the contact is uncertain, so the isochore provides the range around it."]'::jsonb, 0, 'Column height is the smaller of contact minus top and the isochore thickness, node by node. At P-1 a 1560 m contact gives a contact-limited 17.38 m, while a 1600 m contact would give a sand-limited 34.05 m.'),
  ('mapping', 'intermediate', 'module', 'm05-what-an-isochore-is-for', 10, 'At a node the top surface is 1550 m, the isochore reads 28 m and the contact is at 1570 m. What is the column and what limits it?', '["28 m, sand-limited, because the isochore is the smaller of the two candidate columns.", "20 m, contact-limited, since the contact sits 20 m below the top and the sand is thicker.", "48 m, since the column runs from the top of the sand to the base of the interval below the contact.", "8 m, the difference between the sand thickness and the depth of the contact below the top."]'::jsonb, 1, 'The contact is 1570 minus 1550, which is 20 m below the top, and 20 is smaller than the 28 m of sand available.'),
  ('mapping', 'intermediate', 'module', 'm05-what-an-isochore-is-for', 11, 'The Ekene isochore thins toward the northeast. Which stories fit that observation?', '["Depositional thinning only, since onlap and truncation would both produce a mapped zero somewhere.", "Depositional thinning, onlap against a high, or erosion at the top or the base of the interval.", "Erosion at the top only, since a depositional story would show a thickness gradient rather than a corner.", "None of them, because six wells cannot support any depositional reading at all."]'::jsonb, 1, 'All of them produce the same map and the map cannot separate them. Logs on a flattened section would show whether the loss is at the top, the base or distributed, and seismic would distinguish onlap and truncation geometries.'),
  ('mapping', 'intermediate', 'module', 'm05-what-an-isochore-is-for', 12, 'How many wells define the thinning direction on the Ekene isochore, and what follows?', '["Two, Ekene-4 and Ekene-2 at opposite ends of the range, which is enough to establish a gradient.", "Six, since every well contributes a thickness to the spline that produced the trend.", "One, Ekene-4, so the direction is a hypothesis supported by a single control point.", "Three, the northeastern wells, whose thicknesses fall in sequence toward the corner."]'::jsonb, 2, 'Remove Ekene-4 and the map loses its thin corner and the northeast trend with it. Between the wells the contours are the spline''s opinion rather than the field''s.'),
  ('mapping', 'intermediate', 'module', 'm05-what-an-isochore-is-for', 13, 'Which sentence about the isochore is the professional one to write?', '["The isochore shows a channel axis trending north-northwest across the field.", "The isochore is too poorly controlled to support any statement about thickness variation.", "The isochore confirms depositional thinning away from a sediment source in the southwest.", "The isochore thins from the centre and south to 25 m at Ekene-4, controlled by one well."]'::jsonb, 3, 'It commits to the observation and declines to commit to the interpretation, which is what lets a reader act on it. The channel-axis version sounds more expert and asserts something six wells cannot support.'),
  ('mapping', 'intermediate', 'module', 'm05-what-an-isochore-is-for', 14, 'Which two of the five ways a thickness map misleads does the Ekene isochore actually exhibit at the capstone settings?', '["A negative thickness somewhere on the map, and a live node count smaller than the depth map''s.", "A control count of twelve rather than six, and a mapped area larger than the well pattern.", "A contour interval finer than the depth map''s, and a crest that overshoots the shallowest pick.", "A misplaced maximum 50 m from Ekene-2, and a mean gap of 1.088 m against the wells."]'::jsonb, 3, 'The maximum moves to exactly 36 m at a 50 m cell, and the map mean sits 1.088 m above the well mean. The map does look like a measurement and its blanks are silent, but those are properties of every isochore rather than readings on this one.'),
  ('mapping', 'intermediate', 'module', 'm05-what-an-isochore-is-for', 15, 'A base pick is missing from one edge well. Why is that the hardest failure to see?', '["Because the spline extrapolates a base value at that well, so the isochore reports a thickness that was never measured.", "Because the missing pick makes the isochore negative in that corner, which is easy to mistake for a sign error.", "Because the depth map still covers 201 nodes while the thickness map covers 133, and both contour cleanly.", "Because the well mean and the map mean both change, so the usual gap check no longer applies."]'::jsonb, 2, 'A volume from the isochore then covers two thirds of the structure while being reported against the depth map''s outline. Only the node counts announce it, which is why they belong on the map.'),
  ('mapping', 'intermediate', 'module', 'm06-the-isochore-workflow', 1, 'Which step of the isochore workflow runs before any gridding at all?', '["Deriving the frame from the union of the control points.", "Checking that the isochore mean equals the difference of the two surface means.", "Sanity-checking the six well thicknesses by subtracting each well''s own picks.", "Refining the cell size and re-reading the extremes."]'::jsonb, 2, 'It costs nothing and catches swapped or mis-picked tops while they are still cheap to fix. A negative thickness is a swapped pick and an outlier is either a mis-pick or a genuinely interesting well.'),
  ('mapping', 'intermediate', 'module', 'm06-the-isochore-workflow', 2, 'Why does confirming that both picks exist in every well come first in the workflow?', '["Because it changes which wells are in the control set, and so everything after.", "Because a well with one pick produces a negative thickness that contaminates the mean.", "Because the gridder refuses to run when a control point is missing a value.", "Because the capstone grades the well count as an exact field."]'::jsonb, 0, 'A well with a top and no base contributes to one surface and not the other, which shrinks the isochore''s mask without touching the depth map.'),
  ('mapping', 'intermediate', 'module', 'm06-the-isochore-workflow', 3, 'What is wrong with gridding each surface at whatever settings it seems to need and subtracting afterwards?', '["Nothing, provided both grids are resampled onto a common frame before the subtraction.", "The isochore becomes a map of the difference between two sets of settings.", "The two surfaces will honour their wells at different levels of exactness.", "The subtraction will fail, because grids from different settings have different array lengths."]'::jsonb, 1, 'Each choice is defensible in isolation, which is what makes the combination dangerous. Surfaces destined to be combined are gridded as a set, with one decision about settings applied to all of them.'),
  ('mapping', 'intermediate', 'module', 'm06-the-isochore-workflow', 4, 'A project has TOP_SAND in eight wells and BASE_SAND in six of them. What does step 1 force?', '["A decision between an isochore covering less ground than the depth map and dropping two wells from both.", "The exclusion of the two wells, since surfaces that will be combined must share a control set.", "The interpolation of two base picks from the surrounding wells, so that both surfaces have eight control points.", "Nothing, since the mask intersection handles the difference automatically and correctly."]'::jsonb, 0, 'Neither answer is automatically right. Excluding them makes the maps comparable and throws away real depth control; keeping them makes the depth map better and the isochore''s coverage smaller, and a reader cannot recover the choice from the maps.'),
  ('mapping', 'intermediate', 'module', 'm06-the-isochore-workflow', 5, 'Which of the three arithmetic checks catches two surfaces that do not share a live node set?', '["That every mapped thickness is positive.", "That the isochore minimum is not the difference of the two surface minima.", "That the isochore mean equals the difference of the two surface means.", "That the isochore maximum lies at or below the thickest well."]'::jsonb, 2, 'The equality 1582.5211 minus 1550.2668 equals 32.2543 holds only when both means are taken over the same nodes, because averaging is linear over a shared live set.'),
  ('mapping', 'intermediate', 'module', 'm06-the-isochore-workflow', 6, 'The isochore minimum is 25 m while the two surface minima differ by 1570 minus 1539.7181, which is 30.28 m. Why is that expected?', '["Because the mask removes the node where the top surface reaches its minimum.", "Because the two surfaces reach their extremes at different nodes, so only linear operations survive the subtraction.", "Because the minimum of the isochore is computed before the mask is applied.", "Because the top surface minimum is a spline overshoot and the base minimum is a well value."]'::jsonb, 1, 'A mean is linear and subtracts exactly; a minimum is not. If the two ever did agree it would be worth understanding why, because it would mean both surfaces reach their extremes at the same node.'),
  ('mapping', 'intermediate', 'module', 'm06-the-isochore-workflow', 7, 'A base surface has fewer live nodes than the top surface it will be subtracted from. What is that?', '["An error in the mask, which must be recomputed from the union of the two control sets.", "A failure of the workflow, since surfaces to be combined must have equal coverage.", "A sign that the base picks are less reliable and should be down-weighted in the fit.", "A coverage statement that has to reach the report rather than a fault to be repaired."]'::jsonb, 3, 'It is normal and it is not an error. The temptation is to adjust a setting until the counts match, which converts a map that reports its own coverage into one that has been tuned.'),
  ('mapping', 'intermediate', 'module', 'm06-the-isochore-workflow', 8, 'Which check tests the whole workflow with a single number, at the cost of one extra gridding run?', '["Sampling the isochore at every well and comparing against the measured thicknesses.", "Building the isochore the other way, by gridding the six well thicknesses directly, and comparing.", "Refining the cell size to 50 m and re-reading the minimum and the maximum.", "Comparing the map mean against the well mean and checking the sign of the gap."]'::jsonb, 1, 'On a disciplined workflow the two routes agree to 0.00011 m. A larger disagreement means either that the control locations differ between the surfaces, usually a missing pick, or that the two were not gridded the same way.'),
  ('mapping', 'intermediate', 'module', 'm06-the-isochore-workflow', 9, 'An isochore has a mean of 31.9 m, a minimum of minus 2.4 m and a maximum of 44 m over 180 live nodes against a depth map''s 201. What do the checks say?', '["The map is usable, since one negative node in an otherwise positive map is within tolerance.", "The map has a global sign error, which is fixed by subtracting in the other order.", "The negative minimum fails outright, and the 180 against 201 is a separate coverage finding.", "The 180 against 201 fails outright, and the negative minimum follows from the missing coverage."]'::jsonb, 2, 'A single negative node is not a global sign error, which would make everything negative. It is one well with swapped picks, or two surfaces crossing where the spline has overshot between sparse control, and it must be fixed before any other check is trusted.'),
  ('mapping', 'intermediate', 'module', 'm06-the-isochore-workflow', 10, 'Which capstone field is graded with a tolerance of zero?', '["The live isochore node count.", "The mean of the six well thicknesses.", "The isochore minimum thickness.", "The thickness at prospect P-1."]'::jsonb, 0, 'It is a count of nodes rather than a measurement of anything, so 200 is not 201. The well mean carries the tightest measurement tolerance at 0.05 m and the four gridded thickness fields carry 0.1 m.'),
  ('mapping', 'intermediate', 'module', 'm06-the-isochore-workflow', 11, 'What is the first thing to do when running the isochore capstone?', '["Read the live node count, since it fixes which settings the other fields came from.", "Set the cell size to 100 m and confirm the tile reads 100 before recording anything.", "Switch the surface control to the isochore, since four of the six fields are read there.", "Compute the well mean, since it is the only field that needs no map."]'::jsonb, 1, 'Four of the six fields move if the cell size changes, and the commonest failure is reading one field from a different setting than the others.'),
  ('mapping', 'intermediate', 'module', 'm06-the-isochore-workflow', 12, 'A learner submits 25, 36, 32.25, 34.05, 201 and 31.17. Which field is wrong?', '["The mean, which should be 32.2543 rather than 32.25 at the graded precision.", "The live node count, which is 200 at a 100 m cell rather than 201.", "The maximum, which is the 50 m cell reading and misses the 0.1 m tolerance.", "The value at P-1, which should be read from the top surface rather than the isochore."]'::jsonb, 2, '36 is correct at a 50 m cell and the capstone''s 100 m cell gives 35.8977, a difference of 0.102 m. The consistency checks do not catch it, because 36 sits perfectly well above the mean.'),
  ('mapping', 'intermediate', 'module', 'm06-the-isochore-workflow', 13, 'Which self-consistency check would catch a learner who has swapped the two means?', '["The mean must lie between the minimum and the maximum.", "The live count times the cell area should be about two square kilometres.", "The base surface minus the top surface at P-1 should equal the thickness there.", "The map mean should exceed the well mean by about a metre on this field."]'::jsonb, 3, 'A gap of zero or a negative gap means the two have been crossed. The two numbers are 31.17 and 32.25, so the error is more than ten times the 0.1 m tolerance.'),
  ('mapping', 'intermediate', 'module', 'm06-the-isochore-workflow', 14, 'What does leave-one-out validation, the Expert tier''s first technique, measure?', '["How much the mapped surface changes when the cell size is halved and the mask is held fixed.", "How far the map mean moves when the least reliable well is removed from the control.", "How much of the mapped area lies more than 800 m from any control point.", "How far the map''s prediction at a withheld well falls from the pick that was withheld."]'::jsonb, 3, 'Dropping a well, regridding the rest and comparing the prediction against the withheld pick is a measurement of predictive skill at a place where the truth happens to be known.'),
  ('mapping', 'intermediate', 'module', 'm06-the-isochore-workflow', 15, 'Why can leave-one-out not be run at most of the Ekene wells?', '["Because the gridder masks to the control, so a removed outer well ends up outside what the remaining five constrain.", "Because removing a hull well changes the frame, so the two runs are no longer comparable.", "Because five of the six wells do not land on grid nodes, so no prediction can be sampled at them.", "Because the spline refuses to fit fewer than six control points on this frame."]'::jsonb, 0, 'Removing each of the five outer wells drops the live node count from 201 to somewhere between 130 and 183, and their own locations fall outside the surviving map. Only the interior well leaves the count at 201.'),
  ('mapping', 'intermediate', 'final', null, 1, 'Which set of six values is the Ekene isochore capstone answer key at a 100 m cell?', '["25, 36, 32.2543, 34.0500, 201 and 31.1667.", "25, 35.8977, 32.2543, 34.0500, 201 and 31.1667.", "25, 35.8977, 31.1667, 34.0500, 500 and 32.2543.", "26.7332, 35.8977, 32.2720, 34.0500, 50 and 31.1667."]'::jsonb, 1, 'Minimum 25 m, maximum 35.897705078125 m, map mean 32.25429068038713 m, thickness at P-1 34.050048828125 m, 201 live nodes and a well mean of 31.166666666666668 m. The 36 belongs to a 50 m cell and the last option is the 200 m reading.'),
  ('mapping', 'intermediate', 'final', null, 2, 'A colleague reports an isochore mean of 32.25 m and a well mean of 32.25 m on a six-well field. What should you suspect?', '["That the two are the same number by coincidence, which is unremarkable on a small field.", "That the map has been tuned to reproduce the well average, or the same number has been quoted twice.", "That the mask has been widened until the two agree, which is standard practice.", "That the well set is unbiased, which is what makes the two means agree."]'::jsonb, 1, 'A gap of zero would mean the area weighting happened to cancel exactly, which is a coincidence rather than a confirmation. On Ekene the gap is 1.088 m and about two thirds of it is the area weighting alone.'),
  ('mapping', 'intermediate', 'final', null, 3, 'Which quantity is unchanged when the isochore is regridded at 50 and 200 m?', '["The mapped maximum.", "The live node count.", "The thickness at prospect P-1.", "The contour interval."]'::jsonb, 2, 'P-1 lands on a node in all three frames and a node value is the fit itself, so it reads 34.050048828125 m every time. The other three all move.'),
  ('mapping', 'intermediate', 'final', null, 4, 'Why is the mapped area of 2.01 square kilometres a setting as much as a fact?', '["Because it is the hull of six wells clipped at 800 m, and both the hull and the limit are choices.", "Because the cell area of 10,000 square metres is fixed by the capstone rather than by the field.", "Because the frame is padded by two cells, which adds area the wells do not constrain.", "Because the area is computed from the live count, which is rounded to the nearest node."]'::jsonb, 0, 'Widen the extrapolation limit and the area grows; change the control set and the hull changes. That is why every mapped statistic travels with its live node count and mask setting.'),
  ('mapping', 'intermediate', 'final', null, 5, 'Two grids are subtracted after being built on frames whose origins differ by one cell in y. Which check catches it?', '["Sampling the isochore at every well and comparing against the measured thicknesses.", "Comparing the two frames field by field, or better, never building two frames.", "Checking that the isochore has no negative values anywhere on the map.", "Refining the cell size and confirming that the extremes settle onto control values."]'::jsonb, 1, 'The mean can still come out near the right value, because the surfaces are smooth and a one-cell shift is small compared with the interval thickness. That is exactly what makes the error dangerous.'),
  ('mapping', 'intermediate', 'final', null, 6, 'What does it mean that the thin-plate spline is linear in its control values?', '["That the fitted surface is a plane through the control points when they are coplanar.", "That the value anywhere is a weighted sum of the control values, with weights set by their locations.", "That the surface varies linearly between adjacent control points, which is why it honours them exactly.", "That the residuals of the fit are linearly distributed around zero."]'::jsonb, 1, 'The system A w = z has a matrix built only from the distances between control points, so scaling or differencing the z values scales or differences the surface. That is why gridding differences and differencing grids agree to rounding.'),
  ('mapping', 'intermediate', 'final', null, 7, 'Which of these would break the agreement between the subtraction route and the direct-gridding route?', '["Reading the two maps at a location that does not land on a grid node.", "Using a 50 m cell for both surfaces instead of 100 m.", "One well having a top pick and no base pick.", "Contouring the two maps at different intervals."]'::jsonb, 2, 'The two systems then have different matrices and the routes diverge, sometimes substantially. Same control locations, same method and settings, and same mask are the three conditions.'),
  ('mapping', 'intermediate', 'final', null, 8, 'The isochore at Ekene-2 is blank while the spline passes exactly through 1565 m and 1601 m at that well. What is the honest way to report the control check?', '["Five of five wells honour exactly, since a blank well is outside the map and does not count.", "The check fails, because a map that cannot report a value at a control well is not fit for use.", "Five of six honour exactly and the sixth cannot be sampled because it lies on the mask boundary.", "Six of six honour exactly, since the fit is exact even though the grid cannot show it."]'::jsonb, 2, 'The information is in the fit; it is the gridded, masked, node-based representation that cannot deliver it. Quietly dropping Ekene-2 and reporting five of five is the answer to avoid.'),
  ('mapping', 'intermediate', 'final', null, 9, 'Which statement about isochore and isopach thickness is correct?', '["Vertical thickness always overstates stratigraphic thickness, by a factor that grows with dip.", "Stratigraphic thickness always overstates vertical thickness, by the secant of the dip.", "The two are equal wherever the interval is thicker than the cell size.", "The two differ only where the dip exceeds 45 degrees, below which the correction is exactly zero."]'::jsonb, 0, 't_isopach = t_isochore cos(theta). At the steepest point of the Ekene field, 3.19 degrees, the correction is 0.05 m on 32.25 m, which is 0.16 percent.'),
  ('mapping', 'intermediate', 'final', null, 10, 'A gross rock volume is computed over a horizontal map area. Which thickness belongs in it?', '["The isopach, since stratigraphic thickness is the true thickness of the bed.", "The isochore, because the vertical overstatement compensates for the map area.", "The isopach, corrected back to vertical only where the dip exceeds 20 degrees.", "Whichever is larger, since a volume should not be understated at the screening stage."]'::jsonb, 1, 'Correcting to stratigraphic thickness and then multiplying by map area would understate the volume. Sedimentology wants the isopach; a volume wants the isochore.'),
  ('mapping', 'intermediate', 'final', null, 11, 'At a dip of 20 degrees, what is the isopach correction on a 32 m isochore?', '["About 1.9 m, or 6 percent.", "About 0.5 m, or 1.5 percent.", "About 4.3 m, or 13 percent.", "About 9.4 m, or 29 percent."]'::jsonb, 0, '1 minus cos(20 degrees) is about 0.060. Below about 10 degrees the correction is smaller than most pick uncertainty; above about 20 degrees it is a first-order error.'),
  ('mapping', 'intermediate', 'final', null, 12, 'The Ekene isochore keeps 201 live nodes, the same as both input surfaces. What would change that?', '["Refining the cell size, which changes the live count on the isochore alone.", "A well with a pick on one surface and not the other, which shrinks the intersection.", "A larger contrast between the two surfaces, since a thicker interval spreads the hull.", "Subtracting in the other order, which reverses the intersection into a union."]'::jsonb, 1, 'The mask is computed from control locations alone, so identical control geometry gives identical live sets. Drop Ekene-4''s base pick and the isochore falls to 133 nodes while the depth map keeps 201.'),
  ('mapping', 'intermediate', 'final', null, 13, 'Why is a blank node in an isochore worse than a zero?', '["Because a blank breaks the array arithmetic while a zero contributes nothing and is harmless.", "Because a blank cannot be contoured, so the map has a hole in it that a reader will ask about.", "Because a blank reads as absence when what is really there is ignorance about it.", "Because a blank is counted in the live node total while a zero is not."]'::jsonb, 2, 'A reader looking at an uncoloured margin sees no sand, when what is there is no information. The defence is to quote the live node count and the mapped area with every statistic.'),
  ('mapping', 'intermediate', 'final', null, 14, 'Which pair of numbers should travel with any mapped average?', '["The contour interval and the number of levels drawn.", "The control count and the range of the control values.", "The standard deviation and the number of wells.", "The live node count and the mask setting."]'::jsonb, 3, 'On Ekene that is 32.25 m over 201 live nodes at a 100 m cell with an 800 m limit. A well average travels with two things instead: the number and the sample.'),
  ('mapping', 'intermediate', 'final', null, 15, 'Ekene-6 has 68 of the 201 live nodes nearest to it. What does that number explain?', '["Why the map mean sits above the well mean, since a thick well gains weight.", "Why the map honours Ekene-6 exactly while it cannot report a value at Ekene-2.", "Why removing Ekene-6 leaves the live node count unchanged at 201.", "Why the thick spot of the isochore sits near Ekene-2 rather than near Ekene-6."]'::jsonb, 0, 'Ekene-6 at 34 m gains the most weight and Ekene-4 at 25 m loses the most, which moves the area-weighted well mean to 31.801 m. The spline shape supplies the remaining 0.453 m of the gap.'),
  ('mapping', 'intermediate', 'final', null, 16, 'A field is mapped from six wells and the thinnest well sits in the middle of the pattern. What follows for the two means?', '["The map mean would still exceed the well mean, since a spline overshoots above its control on any geometry.", "The two means would agree, since a central thin well balances the thick wells on the hull.", "The map mean would fall below the well mean, because the area weighting promotes the interior well.", "The gap would depend on the cell size rather than on the geometry, so no direction can be predicted."]'::jsonb, 2, 'The direction of the gap is set by where the thick and thin wells sit relative to the control geometry. Assuming a direction from experience on one field is how the error becomes invisible on the next.'),
  ('mapping', 'intermediate', 'final', null, 17, 'The contour rule targets ten intervals and the Ekene isochore comes out with five. Why?', '["Because the rule rounds the interval up to a nice number, so the realised count is at or below ten.", "Because the mask removes the nodes where the outermost two contour levels would have run.", "Because a thickness map is contoured at half the density of a depth map by convention.", "Because five of the ten levels fall outside the range once the extremes are excluded."]'::jsonb, 0, 'A tenth of the 10.90 m range is 1.09, which rounds up to 2 and nearly halves the count. How far below ten it lands depends on where the range falls relative to the nice-number ladder.'),
  ('mapping', 'intermediate', 'final', null, 18, 'A thickness map runs from 12.4 to 41.8 m. What interval will the rule choose?', '["2 m, giving fifteen levels.", "3 m, giving ten levels.", "10 m, giving three levels.", "5 m, giving six levels."]'::jsonb, 3, 'The range is 29.4 m, a tenth of it is 2.94, and the rule rounds up to the next nice number. The loss is worse than on the Ekene isochore because 2.94 sits just above 2 and is pushed almost all the way to 5.'),
  ('mapping', 'intermediate', 'final', null, 19, 'Which map on this course carries the finest contour interval, and what does that say about it?', '["The isochore at a 200 m cell, at 1 m, and it is the map built from the fewest nodes.", "The isochore at a 50 m cell, at 1 m, and it is the best resolved map in the course.", "The depth map at a 100 m cell, at 10 m, since depth has the widest range.", "The isochore at a 100 m cell, at 2 m, and it is the map the capstone grades."]'::jsonb, 0, 'At 200 m the map loses Ekene-4''s node, the range falls to 9.16 m and a tenth of that rounds to 1. The coarsest grid, with 50 live nodes rather than 201, ends up with the most contour lines.'),
  ('mapping', 'intermediate', 'final', null, 20, 'Why does refining the cell from 100 m to 50 m move the isochore maximum but not the minimum?', '["Because the maximum is a spline overshoot and the minimum is a control value.", "Because Ekene-2 gains a node at 50 m while Ekene-4 already lands on one at 100 m.", "Because the mask reaches further at 50 m, which adds thick nodes near Ekene-2.", "Because the maximum is computed before the mask is applied and the minimum after."]'::jsonb, 1, 'Ekene-2 at (2200, 1150) needs a 50 m row to land on a node, at which point the maximum becomes exactly its measured 36 m. Ekene-4 at (2600, 2500) is on a node at every setting.'),
  ('mapping', 'intermediate', 'final', null, 21, 'What is the mapped thickness at P-1 evidence for?', '["That a spline through six wells predicts 34.05 m at that location.", "That the reservoir at P-1 is 34.05 m thick, within the 0.1 m capstone tolerance.", "That the interval between Ekene-6 and Ekene-3 is uniform at about 34 m.", "That a well at P-1 would encounter between 25 and 36 m of sand."]'::jsonb, 0, 'It is a statement about the interpolation and it is exactly true. It is not a measurement, and it carries no spread, which is the Expert tier''s question.'),
  ('mapping', 'intermediate', 'final', null, 22, 'A colleague quotes 34.05 m at P-1 as a fixed input to a volume estimate. What are the two objections?', '["That the precision implies a resolution the picks do not have, and that the value needs a range around it.", "That the value was read at the wrong cell size, and that P-1 does not land on a grid node.", "That the value is an isopach rather than an isochore, and that volumes want vertical thickness.", "That the value came from the map rather than from the wells, and only measured thicknesses may enter a volume."]'::jsonb, 0, 'Neither objection says the number is wrong. Both say it needs its conditions attached.'),
  ('mapping', 'intermediate', 'final', null, 23, 'Which is the correct order for the first five steps of the isochore workflow?', '["Confirm both picks, derive one frame, grid both surfaces, sanity-check the thicknesses, subtract deep minus shallow.", "Sanity-check the thicknesses, confirm both picks, grid both surfaces, derive one frame, subtract deep minus shallow.", "Confirm both picks, sanity-check the thicknesses, derive one frame, grid both surfaces, subtract deep minus shallow.", "Derive one frame, confirm both picks, sanity-check the thicknesses, subtract deep minus shallow, grid both surfaces."]'::jsonb, 2, 'Confirming the picks comes first because it changes the control set, and the thickness check runs before any gridding because it costs nothing and catches a swapped pick while it is cheap.'),
  ('mapping', 'intermediate', 'final', null, 24, 'Which failure does step 5, subtract deep minus shallow, protect against?', '["An isochore that covers less ground than the depth map above it.", "A thickness map of negative numbers, which contours perfectly well.", "A mis-pick reaching a map before anyone has looked at the six thicknesses.", "Two grids that disagree about where node zero sits."]'::jsonb, 1, 'Contouring does not care about sign, so the error survives every visual check. Confirming the sign at one well before trusting the map costs seconds.'),
  ('mapping', 'intermediate', 'final', null, 25, 'An isochore quality check reports every value positive, a mean equal to the difference of the surface means, and a minimum that is not the difference of the two minima. What has been established?', '["That the map is correct, since all three arithmetic checks have passed.", "That the sign, the shared live set and the placement of the extremes are consistent.", "That the two surfaces were gridded with identical settings, which the mean check proves.", "That the control honouring is exact at every well that lands on a node."]'::jsonb, 1, 'Three unrelated points are pinned, which is what makes the trio worth running. Control honouring, frame agreement and the two-route cross-check are separate checks.'),
  ('mapping', 'intermediate', 'final', null, 26, 'Which response to a failed check converts a broken map into a tuned one?', '["Reporting a mismatched live node count as a coverage statement.", "Describing an extreme that will not settle under refinement as spline behaviour.", "Adjusting a setting until the check passes.", "Fixing a crossing surface and re-running every other check afterwards."]'::jsonb, 2, 'A tuned map agrees with whatever it was tuned to and with nothing else. Each check fails for a different reason, which is the point of holding nine of them.'),
  ('mapping', 'intermediate', 'final', null, 27, 'Which capstone field would change if the BASE_SAND pick were missing from Ekene-4?', '["Only the live node count, which would fall from 201 to 133.", "Only the mean of the six well thicknesses, which would become a mean of five.", "None of them, since the mask intersection is computed after the statistics.", "The live count, the two extremes, the map mean and the well mean."]'::jsonb, 3, 'The base surface would lose the northeast corner, so the isochore falls to 133 live nodes and every statistic over the node set moves. Only the depth at P-1 on the top surface would be untouched.'),
  ('mapping', 'intermediate', 'final', null, 28, 'Why does the capstone fix the cell size at 100 m before grading the live node count exactly?', '["Because 201 is the count at which the mask and the hull agree, which is the defensible setting.", "Because the count is a property of the setting rather than the rock, so the setting must be pinned.", "Because a 100 m cell is the finest setting at which the spline remains stable on six control points.", "Because the count enters the volume calculation, which the capstone grades to the nearest cubic metre."]'::jsonb, 1, 'The count reads 794, 201 or 50 at 50, 100 and 200 m, and every one of those correctly answers the question it asks. Fixing the setting is what makes an exact tolerance fair.'),
  ('mapping', 'intermediate', 'final', null, 29, 'Two maps of the same horizon from different vintages are contoured by the automatic rule and their intervals differ. What should be done before they are compared?', '["Fix the interval by hand, since a reader reads line density as geology.", "Regrid both at the finer of the two cell sizes, which makes the ranges comparable.", "Report only the map with the finer interval, since it carries more information.", "Rescale the colour of both maps to the union of the two ranges."]'::jsonb, 0, 'An automatic rule changes the interval whenever the range changes, which happens as soon as a well is added. Quoting the interval with the cell size is the other habit.'),
  ('mapping', 'intermediate', 'final', null, 30, 'What does the well mean of 31.1667 m weight equally?', '["The six wells, regardless of how much area each of them represents.", "The 201 live nodes, each standing for 10,000 square metres.", "The two surfaces, since each contributes six picks to the calculation.", "The measured and the mapped thicknesses at each well."]'::jsonb, 0, 'A well in a corner counts as much as a well in the middle of the field. That is why the number is a summary of what has been measured rather than an estimate of the field average.'),
  ('mapping', 'intermediate', 'final', null, 31, 'Which reading is the direct measurement of why the two means differ?', '["The live node count of 201 against the frame''s 500 nodes.", "The contour interval of 2 m against the depth map''s 10 m.", "The tile reading 146 of 201 live nodes above the well mean.", "The map mean of 32.2543 m against the maximum of 35.8977 m."]'::jsonb, 2, 'Only 55 nodes sit below the well mean, so 73 percent of the mapped area is above the average of the wells. That asymmetry is the gap.'),
  ('mapping', 'intermediate', 'final', null, 32, 'Between the isochore and a recoverable hydrocarbon volume, which multipliers stand in the way?', '["Net-to-gross, porosity, saturation with a contact, then recovery factors.", "Porosity and a recovery factor, since net-to-gross is already applied by the mask.", "A contact and a recovery factor, since the isochore is already a net thickness.", "Net-to-gross and a formation volume factor, since saturation is carried by the contact."]'::jsonb, 0, 'Each multiplies the number by a fraction less than one, which is why gross rock volume is the largest figure in the chain and the easiest to quote out of context.'),
  ('mapping', 'intermediate', 'final', null, 33, 'The volumetrics course reports 22.27 million cubic metres against this course''s 64.83 million. Which statement is right?', '["The larger figure is a gross rock volume and the smaller a pore volume of the same rock.", "The smaller figure supersedes the larger, which was computed before a contact was available.", "The two disagree because the volumetrics course grids the surfaces itself with different settings.", "Both are correct and cover different things, the whole interval and the part above a contact."]'::jsonb, 3, 'The contact throws away every node where the top is deeper than 1560 m and counts only the column above it at the nodes it keeps.'),
  ('mapping', 'intermediate', 'final', null, 34, 'At P-1 the top is 1542.62 m and the sand is 34.05 m thick. At what contact depth does the column stop being contact-limited?', '["At 1560 m, where the contact sits 17.38 m below the top.", "At about 1576.67 m, where the contact reaches the base of the sand.", "At 1590 m, the deepest mapped value on the top surface.", "At 1600 m, where the implied column is 57.38 m."]'::jsonb, 1, '1542.62 plus 34.05 is 1576.67 m, the base of the sand at that location. Below that the sand does the limiting and deepening the contact adds nothing there.'),
  ('mapping', 'intermediate', 'final', null, 35, 'Which evidence would separate depositional thinning from erosional truncation on the Ekene isochore?', '["A finer cell size, which would resolve the shape of the thinning at Ekene-4.", "The map mean against the well mean, since erosion would break the area weighting.", "Logs correlated on a flattened section, which show where the section is lost.", "The contour interval, which is finer over a truncated interval than a depositional one."]'::jsonb, 2, 'Seismic would distinguish onlap and truncation geometries directly, and a single well northeast of Ekene-4 would say more than any amount of reinterpretation.'),
  ('mapping', 'intermediate', 'final', null, 36, 'Which of the five ways a thickness map misleads is answered by stating the control count on the map?', '["That the extremes are not where you think.", "That the mean is not the well average.", "That the blanks are silent.", "That it looks like a measurement."]'::jsonb, 3, 'Six wells constrain the isochore, the same six that constrain the two depth surfaces, and two maps of six points do not make a map of twelve.'),
  ('mapping', 'intermediate', 'final', null, 37, 'A thickness map is presented with a 1 m contour interval, a mean of 30.4 m and a coverage of 4.2 square kilometres. Which question does the contour interval fail to answer?', '["How many contour levels were drawn.", "What the range of the mapped values is.", "Whether the map has been contoured by an automatic rule.", "How many wells control the map."]'::jsonb, 3, 'The interval is chosen from the range and knows nothing about control. The other two questions to ask are what cell size and mask produced the 4.2 square kilometres, and whether the mean is the map mean or the well mean.'),
  ('mapping', 'intermediate', 'final', null, 38, 'Why does a 3 m change in a mapped value at a prospect between a 100 m and a 50 m grid not indicate an unstable map?', '["Because a 3 m change is inside the 0.1 m tolerance the capstone allows on gridded fields.", "Because the mask reaches further at 50 m, which adds nodes around the prospect.", "Because the spline is refitted at each cell size, so a change of a few metres is expected.", "Because the prospect is bilinearly interpolated in at least one of the two frames."]'::jsonb, 3, 'A node value does not change with cell size at all. Bilinear interpolation between nodes of a curved surface undershoots the curvature, and that undershoot scales with the square of the cell size.'),
  ('mapping', 'intermediate', 'final', null, 39, 'Which habit does the Expert tier inherit from this one, because validation grids the same field six or seven times?', '["One control set, never varied.", "One contour interval, fixed by hand.", "One cell size, always the finest available.", "One frame, reused across every run."]'::jsonb, 3, 'If the runs are not on a shared frame the residuals are measuring the frame. Varying the control set is precisely what the Expert tier does.'),
  ('mapping', 'intermediate', 'final', null, 40, 'What is the jackknife spread at a prospect for?', '["It measures how much the map changes when the cell size is varied over its plausible range.", "It measures the difference between the map mean and the well mean at the prospect''s node.", "It measures the residual at the one well that can be cross-validated on this geometry.", "It measures how far the mapped value at a prospect moves as each well is dropped."]'::jsonb, 3, 'Six control sets give six answers and their spread is an uncertainty estimate at a location with no well, computed entirely from data already in hand.'),
  ('mapping', 'intermediate', 'final', null, 41, 'Which statement about what this tier produced is accurate?', '["It replaced the Associate tier''s depth map with a better constrained one.", "It validated the isochore against the wells, which is why five of six honour exactly.", "It quantified how far wrong the mapped thickness at P-1 is likely to be.", "It built an instrument and did not test it, since nothing here measured predictive skill."]'::jsonb, 3, 'Every number here is a property of an interpolation. Whether the spline predicts well, and how far wrong it is likely to be at a location with no well, are Expert tier questions.'),
  ('mapping', 'intermediate', 'final', null, 42, 'Volumetrics consumes the top surface, the isochore and the mask without rechecking any of them. What follows?', '["That the volumetrics course will detect a bad pick when its own capstone fails to reproduce.", "That the mapping course should hand over statistics as well, so the numbers can be cross-checked downstream.", "That validation upstream is the only thing standing between an interpolation and a booked volume.", "That the mask should be widened before hand-off, so that no volume is left unclaimed."]'::jsonb, 2, 'Each link consumes the previous one without re-deriving it, so nobody downstream will rediscover a bad pick or an over-extrapolated node.');
